<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root='/home/u783725167/domains/cortarimagenscarrossel.online/public_html';
$backup=dirname($root).'/cic-adsense-backup-20261102/merge-guides';
require_once $root.'/db_config.php';
$mysqli->set_charset('utf8mb4');
$changes=[
['slug'=>'ferramenta-online-para-cortar-imagens-de-carrossel-no-instagram','anchor'=>'<h2>Exemplo com 5 partes</h2>','add'=>base64_decode('')],
['slug'=>'como-evitar-perda-de-qualidade-no-carrossel-instagram','anchor'=>'<h2>Comece pela dimensão de cada slide</h2>','add'=>base64_decode('')]
];
$planned=[];$snapshots=[];
foreach($changes as $c){
 $s=$mysqli->prepare('SELECT id,slug,content FROM posts WHERE slug=? LIMIT 1');
 $s->bind_param('s',$c['slug']);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();
 if(!$row){echo "SLUG_MISSING ".$c['slug']."\n";exit(1);}
 if(strpos($row['content'],'cic-merge-')!==false){echo "ALREADY ".$c['slug']."\n";continue;}
 if(substr_count($row['content'],$c['anchor'])!==1){echo "ANCHOR_ERR ".$c['slug']."\n";exit(1);}
 $snapshots[]=$row;
 $planned[]=['id'=>(int)$row['id'],'slug'=>$row['slug'],'content'=>str_replace($c['anchor'],$c['add']."\n".$c['anchor'],$row['content'])];
}
if(!$planned){echo "MERGE_ALREADY_DONE\n";exit;}
if(!is_dir($backup)&&!mkdir($backup,0750,true)){echo "BACKUP_DIR_ERR\n";exit(1);}
$path=$backup.'/before_merge.json';
if(!file_exists($path)&&file_put_contents($path,json_encode($snapshots,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX)===false){echo "BACKUP_ERR\n";exit(1);}
try{
 $mysqli->begin_transaction();
 $stmt=$mysqli->prepare('UPDATE posts SET content=? WHERE id=?');
 foreach($planned as $p){$content=$p['content'];$id=$p['id'];$stmt->bind_param('si',$content,$id);$stmt->execute();echo "UPDATED ".$p['slug']."\n";}
 $stmt->close();$mysqli->commit();echo "MERGE_CONTENT_DONE\n";
}catch(Throwable $e){$mysqli->rollback();echo "DATABASE_ERROR ".get_class($e)."\n";exit(1);}
